const KR_HOLIDAYS = [
  '2025-01-01','2025-01-28','2025-01-29','2025-01-30',
  '2025-03-01','2025-05-05','2025-05-06','2025-06-06',
  '2025-08-15','2025-10-03','2025-10-05','2025-10-06','2025-10-07','2025-10-09',
  '2025-12-25',
  '2026-01-01','2026-02-16','2026-02-17','2026-02-18',
  '2026-03-01','2026-05-05','2026-06-06',
  '2026-08-17','2026-09-24','2026-09-25','2026-09-26',
  '2026-10-03','2026-10-09','2026-12-25'
];

const now = new Date();
const kst = new Date(now.getTime() + 9 * 3600000);
const pad = n => String(n).padStart(2,'0');
const today = `${kst.getUTCFullYear()}-${pad(kst.getUTCMonth()+1)}-${pad(kst.getUTCDate())}`;
const dow = kst.getUTCDay();

if (KR_HOLIDAYS.includes(today) || dow === 0 || dow === 6) {
  return [{ json: { skip: true, reason: KR_HOLIDAYS.includes(today) ? 'holiday' : 'weekend', today } }];
}

let sinceDate;
if (dow === 1) {
  const fri = new Date(kst.getTime() - 3 * 86400000);
  sinceDate = `${fri.getUTCFullYear()}-${pad(fri.getUTCMonth()+1)}-${pad(fri.getUTCDate())}`;
} else {
  const yst = new Date(kst.getTime() - 86400000);
  sinceDate = `${yst.getUTCFullYear()}-${pad(yst.getUTCMonth()+1)}-${pad(yst.getUTCDate())}`;
}

const sinceUnix = Math.floor(new Date(sinceDate + 'T00:00:00+09:00').getTime() / 1000);

return [{ json: { skip: false, today, dayOfWeek: dow, isMonday: dow === 1, sinceDate, sinceUnix } }];

const emails = $input.all();
const dateInfo = $('공휴일 체크 및 날짜 계산').item.json;

const INTERNAL = ['김영철','정예진','홍대영','solardin.com','시스템설계'];
const URGENT = ['긴급','확인','회신','[긴급]','[확인]','[회신]'];
const EXCLUDE = [/no.?reply/i,/noreply/i,/newsletter/i,/notification/i,/donotreply/i,/mailer.daemon/i,/자동발송/i];
const TARGET = 'han@solardin.com';

const getHeader = (email, name) => {
  const h = (email.json.payload?.headers || []).find(h => h.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : (email.json[name] || '');
};

const isUnread = e => (e.json.labelIds || []).includes('UNREAD');
const isInternal = from => INTERNAL.some(s => from.toLowerCase().includes(s.toLowerCase()));
const isUrgent = subj => URGENT.some(k => subj.includes(k));
const isDirect = e => (getHeader(e,'to') + getHeader(e,'delivered-to')).toLowerCase().includes(TARGET.toLowerCase());
const isExcluded = from => EXCLUDE.some(p => p.test(from));

const seen = new Map();
const result = [];

for (const e of emails) {
  const from = getHeader(e,'from');
  const subj = getHeader(e,'subject') || '(제목없음)';
  const date = getHeader(e,'date');
  const snippet = e.json.snippet || '';

  if (isExcluded(from)) continue;
  const unread = isUnread(e);
  const internal = isInternal(from);
  const urgent = isUrgent(subj);
  if (!unread && !internal && !urgent) continue;

  const key = subj.replace(/^(Re:|Fwd:|FW:|답장:|전달:)\s*/gi,'').trim().toLowerCase();
  if (seen.has(key)) continue;
  seen.set(key, true);

  const direct = isDirect(e);
  let priority;
  if (direct && internal) priority = 'P1';
  else if (direct || urgent) priority = 'P2';
  else if (internal) priority = 'P3';
  else priority = 'P4';

  const daysAgo = Math.floor((Date.now() - new Date(date).getTime()) / 86400000);
  result.push({ from, subject: subj, date, dLabel: `D-${daysAgo}`, priority, unread, snippet, internal, urgent, direct });
}

result.sort((a,b) => ({P1:0,P2:1,P3:2,P4:3}[a.priority] - {P1:0,P2:1,P3:2,P4:3}[b.priority]));
return [{ json: { emails: result, dateInfo, total: result.length } }];

const emailData = $('메일 필터링 및 분류').item.json;
const calItems = $('캘린더 5일 조회').all();

const p1p2 = emailData.emails.filter(e => e.priority === 'P1' || e.priority === 'P2').map(e => e.subject.toLowerCase());

const events = calItems.map(e => ({
  title: e.json.summary || '(제목없음)',
  start: e.json.start?.dateTime || e.json.start?.date || '',
  overlap: p1p2.some(s => (e.json.summary||'').toLowerCase().includes(s.substring(0,8)) || s.includes((e.json.summary||'').toLowerCase().substring(0,8)))
}));

return [{ json: { emails: emailData.emails, dateInfo: emailData.dateInfo, calEvents: events } }];

const resp = $input.item.json;
const text = resp.content?.[0]?.text || '브리핑 생성 실패';
return [{ json: { briefingText: text } }];
